@page "/settings"
@using sv_d77c248048ca4c17af92d342774ff3bd.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <h2>Settings</h2>
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @if (isLoading)
        {
            <div class="loading">Loading...</div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <section class="settings-section">
                        <h3>Profile Settings</h3>
                        <div class="profile-layout">
                            <div class="avatar-area">
                                <div class="avatar-preview">
                                    <img src="@editAvatarUrl" alt="Avatar" />
                                </div>
                                <label>Avatar URL</label>
                                <input type="text" @bind="editAvatarUrl" />
                            </div>
                            <div class="profile-fields">
                                <div class="form-group">
                                    <label>Display Name</label>
                                    <input type="text" @bind="editDisplayName" />
                                </div>
                                <div class="form-group">
                                    <label>Email</label>
                                    <input type="email" @bind="editEmail" />
                                </div>
                                <div class="form-group">
                                    <label>Bio</label>
                                    <textarea rows="4" @bind="editBio"></textarea>
                                </div>
                            </div>
                        </div>
                        <div class="button-group">
                            <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                            <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                        </div>
                    </section>
                    break;

                case "Notifications":
                    <section class="settings-section">
                        <h3>Notification Preferences</h3>
                        <div class="toggle-group">
                            <div class="toggle-item">
                                <label class="toggle-label">
                                    <span>Email Notifications</span>
                                    <label class="switch">
                                        <input type="checkbox" @bind="editEmailNotifications" />
                                        <span class="slider"></span>
                                    </label>
                                </label>
                            </div>
                            <div class="toggle-item">
                                <label class="toggle-label">
                                    <span>Push Notifications</span>
                                    <label class="switch">
                                        <input type="checkbox" @bind="editPushNotifications" />
                                        <span class="slider"></span>
                                    </label>
                                </label>
                            </div>
                            <div class="toggle-item">
                                <label class="toggle-label">
                                    <span>Weekly Digest</span>
                                    <label class="switch">
                                        <input type="checkbox" @bind="editWeeklyDigest" />
                                        <span class="slider"></span>
                                    </label>
                                </label>
                            </div>
                        </div>

                        <h4>Muted Channels</h4>
                        <div class="channel-list">
                            @foreach (var channel in allChannels)
                            {
                                <label class="channel-item">
                                    <input type="checkbox"
                                           checked="@editMutedChannels.Contains(channel)"
                                           @onchange="(e) => ToggleMutedChannel(channel, (bool)e.Value!)" />
                                    <span>@channel</span>
                                </label>
                            }
                        </div>
                        <div class="button-group">
                            <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                        </div>
                    </section>
                    break;

                case "Security":
                    <section class="settings-section">
                        <h3>Security Settings</h3>

                        <div class="security-panel">
                            <div class="expandable-header" @onclick="TogglePasswordPanel">
                                <h4>Change Password</h4>
                                <span class="expand-icon">@(showPasswordPanel ? "▾" : "▸")</span>
                            </div>
                            @if (showPasswordPanel)
                            {
                                <div class="expandable-content">
                                    <div class="form-group">
                                        <label>Current Password</label>
                                        <input type="password" @bind="currentPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label>New Password</label>
                                        <input type="password" @bind="newPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label>Confirm Password</label>
                                        <input type="password" @bind="confirmPassword" />
                                    </div>
                                    <button class="btn-primary" @onclick="ChangePassword">Update Password</button>
                                </div>
                            }
                        </div>

                        <div class="toggle-item" style="margin-top: 1.5rem;">
                            <label class="toggle-label">
                                <span>
                                    Two-Factor Authentication
                                    <span class="status-badge @(securitySettings?.TwoFactorEnabled == true ? "enabled" : "disabled")">
                                        @(securitySettings?.TwoFactorEnabled == true ? "Enabled" : "Disabled")
                                    </span>
                                </span>
                                <label class="switch">
                                    <input type="checkbox" @bind="editTwoFactorEnabled" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>

                        @if (securitySettings?.LastPasswordChange != null)
                        {
                            <p class="info-text">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                        }

                        <h4 style="margin-top: 2rem;">Active Sessions</h4>
                        <div class="sessions-table-wrapper">
                            <table class="sessions-table">
                                <thead>
                                    <tr>
                                        <th>Device</th>
                                        <th>Location</th>
                                        <th>Last Active</th>
                                        <th>Action</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    @if (securitySettings?.Sessions != null)
                                    {
                                        @foreach (var session in securitySettings.Sessions)
                                        {
                                            <tr>
                                                <td>@session.Device</td>
                                                <td>@session.Location</td>
                                                <td>@FormatLastActive(session.LastActive)</td>
                                                <td>
                                                    @if (session.Id != "session-1")
                                                    {
                                                        <button class="btn-danger-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                                    }
                                                    else
                                                    {
                                                        <span class="current-badge">Current</span>
                                                    }
                                                </td>
                                            </tr>
                                        }
                                    }
                                </tbody>
                            </table>
                        </div>

                        @if (showRevokeConfirmation)
                        {
                            <div class="modal-overlay" @onclick="CancelRevoke">
                                <div class="modal" @onclick:stopPropagation="true">
                                    <h4>Revoke Session</h4>
                                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong>?</p>
                                    <div class="modal-buttons">
                                        <button class="btn-danger" @onclick="RevokeSession">Revoke</button>
                                        <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                    </section>
                    break;

                case "Appearance":
                    <section class="settings-section">
                        <h3>Appearance Settings</h3>

                        <div class="form-group">
                            <label><strong>Theme</strong></label>
                            <div class="radio-group">
                                <label class="radio-item">
                                    <input type="radio" name="theme" value="Light" @onchange='() => editTheme = "Light"' checked="@(editTheme == "Light")" /> Light
                                </label>
                                <label class="radio-item">
                                    <input type="radio" name="theme" value="Dark" @onchange='() => editTheme = "Dark"' checked="@(editTheme == "Dark")" /> Dark
                                </label>
                                <label class="radio-item">
                                    <input type="radio" name="theme" value="System" @onchange='() => editTheme = "System"' checked="@(editTheme == "System")" /> System
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label><strong>Font Size</strong></label>
                            <div class="radio-group">
                                <label class="radio-item">
                                    <input type="radio" name="fontSize" value="Small" @onchange='() => editFontSize = "Small"' checked="@(editFontSize == "Small")" /> Small
                                </label>
                                <label class="radio-item">
                                    <input type="radio" name="fontSize" value="Medium" @onchange='() => editFontSize = "Medium"' checked="@(editFontSize == "Medium")" /> Medium
                                </label>
                                <label class="radio-item">
                                    <input type="radio" name="fontSize" value="Large" @onchange='() => editFontSize = "Large"' checked="@(editFontSize == "Large")" /> Large
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label><strong>Language</strong></label>
                            <select @bind="editLanguage">
                                <option value="English">English</option>
                                <option value="Spanish">Spanish</option>
                                <option value="French">French</option>
                                <option value="German">German</option>
                                <option value="Japanese">Japanese</option>
                                <option value="Chinese">Chinese</option>
                            </select>
                        </div>

                        <div class="toggle-item">
                            <label class="toggle-label">
                                <span>Compact Mode</span>
                                <label class="switch">
                                    <input type="checkbox" @bind="editCompactMode" />
                                    <span class="slider"></span>
                                </label>
                            </label>
                        </div>

                        <div class="preview-area @(editTheme == "Dark" ? "preview-dark" : "preview-light") @(editCompactMode ? "preview-compact" : "")"
                             style="font-size: @GetPreviewFontSize()">
                            <h5>Live Preview</h5>
                            <p>This is how your content will look with the selected settings.</p>
                            <div class="preview-card">
                                <strong>Sample Card</strong>
                                <p>Theme: @editTheme | Font: @editFontSize | Language: @editLanguage</p>
                            </div>
                        </div>

                        <div class="button-group">
                            <button class="btn-primary" @onclick="SaveAppearance">Save</button>
                        </div>
                    </section>
                    break;
            }
        }
    </main>
</div>

