+
+    .settings-sidebar ul {
+        display: flex;
+        overflow-x: auto;
+    }
+
+    .settings-sidebar li {
+        border-left: none;
+        border-bottom: 3px solid transparent;
+        white-space: nowrap;
+    }
+
+    .settings-sidebar li.active {
+        border-left-color: transparent;
+        border-bottom-color: #0d6efd;
+    }
+
+    .profile-layout {
+        grid-template-columns: 1fr;
+    }
+}
